// v3 (25 Nov 2026). Team sirf `requested_status` chunti hai (dropdown). request_id khud banta hai.
// Body yahin banti hai, taake "Send To Backend" Claim node ke output par depend na kare.
const ALLOWED = ['ORDER_RECEIVED', 'CONFIRMED', 'PREPARING', 'DISPATCHED', 'OUT_FOR_DELIVERY', 'DELIVERED', 'CANCELLED'];
const ALIAS = { RECEIVED: 'ORDER_RECEIVED', NEW: 'ORDER_RECEIVED', PACKED: 'PREPARING' };
const SENTINEL_REVISION = '1970-01-01T00:00:00.000Z'; // revision na ho to website 409 + asal revision lauta deti hai
const MAX_PER_RUN = 5;
const CLAIM_MAX_MS = 10 * 60 * 1000;
const s = v => (v === null || v === undefined ? '' : String(v)).trim();
const norm = v => { const k = s(v).toUpperCase().replace(/[\s-]+/g, '_'); return ALIAS[k] || k; };
const isRevision = v => v.length <= 50 && /^\d{4}-\d{2}-\d{2}T/.test(v) && Number.isFinite(Date.parse(v));
const now = Date.now();
const nowIso = new Date(now).toISOString();
const out = [];
for (const item of $input.all()) {
  if (out.length >= MAX_PER_RUN) break;
  const r = item.json || {};
  const orderId = s(r.order_id);
  const requested = s(r.requested_status);
  if (!orderId || !requested || r.row_number === undefined || r.row_number === null || r.row_number === '') continue;
  const requestIdCell = s(r.request_id);
  if (requestIdCell && requestIdCell === s(r.last_applied_request_id)) continue;
  const syncError = s(r.sync_error);
  if (syncError.indexOf('WF1: IN_PROGRESS') === 0) {
    const m = syncError.match(/@(\S+)/);
    const claimed = m ? Date.parse(m[1]) : NaN;
    if (Number.isFinite(claimed) && now - claimed < CLAIM_MAX_MS) continue;
  }
  const requestId = requestIdCell || ('auto-' + r.row_number + '-' + now.toString(36));
  const sheetStatus = norm(r.status);
  const statusKnown = ALLOWED.includes(sheetStatus);
  const revision = s(r.canonical_status_updated_at);
  const revisionKnown = isRevision(revision);
  const body = {
    source: 'google_sheet',
    eventId: 'sheet:' + (orderId + '-' + requestId).replace(/[^A-Za-z0-9_-]/g, '-').padEnd(8, '0').slice(0, 100),
    orderId,
    status: norm(requested),
    expectedStatus: statusKnown ? sheetStatus : 'ORDER_RECEIVED',
    expectedUpdatedAt: statusKnown && revisionKnown ? revision : SENTINEL_REVISION,
    reason: (s(r.request_reason) || 'Status updated from the Google Sheet').slice(0, 500),
  };
  out.push({ json: {
    row_number: r.row_number,
    request_id: requestId,
    request_created_at: s(r.request_created_at) || nowIso,
    claim_note: 'WF1: IN_PROGRESS @' + nowIso,
    body,
    sheet_status: sheetStatus,
    status_known: statusKnown,
    bootstrap: !(statusKnown && revisionKnown),
    prev_sync_error: syncError,
    original: {
      status: s(r.status), status_revision: s(r.status_revision), canonical_status_updated_at: revision,
      requested_status: requested, request_reason: s(r.request_reason), last_applied_request_id: s(r.last_applied_request_id),
    },
  } });
}
return out;

// v3: website ke jawab se sheet ki row ka naya haal banata hai (Run Once for Each Item).
const p = $('Pending Requests?').item.json;
const res = $json || {};
const httpCode = Number(res.statusCode) || 0;
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
if (!body || typeof body !== 'object') body = {};
const ALLOWED = ['ORDER_RECEIVED', 'CONFIRMED', 'PREPARING', 'DISPATCHED', 'OUT_FOR_DELIVERY', 'DELIVERED', 'CANCELLED'];
const isRevision = v => typeof v === 'string' && v.length <= 50 && /^\d{4}-\d{2}-\d{2}T/.test(v) && Number.isFinite(Date.parse(v));
const stamp = new Date().toISOString();
const o = p.original;
const row = {
  row_number: p.row_number,
  status: o.status, status_revision: o.status_revision, canonical_status_updated_at: o.canonical_status_updated_at,
  requested_status: o.requested_status, request_reason: o.request_reason,
  request_id: p.request_id, request_created_at: p.request_created_at,
  sync_error: '', last_applied_request_id: o.last_applied_request_id,
};
const finishRequest = () => { row.requested_status = ''; row.request_reason = ''; row.request_id = ''; row.request_created_at = ''; };
const takeCanonical = (status, updatedAt) => {
  if (ALLOWED.includes(status)) row.status = status;
  if (isRevision(updatedAt)) { row.canonical_status_updated_at = updatedAt; row.status_revision = updatedAt; }
};
const FRIENDLY = {
  ORDER_NOT_FOUND: 'Ye order website par nahi hai (shayad WhatsApp ka purana order). Website par kuch nahi badla.',
  INVALID_STATUS: 'requested_status samajh nahi aaya. Dropdown se chunein.',
  INVALID_ORDER_ID: 'order_id khaali ya ghalat hai.',
  TERMINAL_STATUS_CONFLICT: 'Delivered/Cancelled order ka status nahi badla ja sakta.',
  INTEGRATION_EVENT_CONFLICT: 'Ye request_id pehle kisi aur tabdeeli ke saath istemal ho chuka. requested_status dobara chunein.',
  INTEGRATION_REVISION_CONFLICT: 'Ye request pehle mukhtalif data ke saath gayi thi. requested_status dobara chunein.',
  QUOTE_REQUIRES_PRICING: 'Quote request ko pehle price karna zaroori hai.',
  INVALID_QUOTE_TRANSITION: 'Order ko quote mein nahi badla ja sakta.',
  INVALID_REASON: 'request_reason 3 se 500 huroof ka hona chahiye.',
};
const code = typeof body.code === 'string' ? body.code : '';
if (httpCode === 200 && body.ok === true) {
  takeCanonical(body.status, body.updatedAt);
  row.last_applied_request_id = p.request_id;
  finishRequest();
} else if (httpCode === 409 && body.canonical && ALLOWED.includes(body.canonical.status) && isRevision(body.canonical.updatedAt)) {
  takeCanonical(body.canonical.status, body.canonical.updatedAt);
  const sameStatus = p.status_known && p.sheet_status === body.canonical.status;
  const alreadyRetried = String(p.prev_sync_error || '').indexOf('WF1: RETRY-REV') === 0;
  if (sameStatus && !alreadyRetried) {
    row.sync_error = 'WF1: RETRY-REV @' + stamp + ' website ki taaza revision likh di, agle minute khud dobara bhejega.';
  } else {
    finishRequest();
    row.sync_error = 'WF1: Website par is order ka status ' + body.canonical.status + ' hai (sheet purani thi). Ab bhi badalna ho to requested_status dobara chunein. [ORDER_CONFLICT]';
  }
} else if ([400, 403, 404, 409, 413, 415].includes(httpCode)) {
  finishRequest();
  row.sync_error = 'WF1: ' + (FRIENDLY[code] || 'Website ne ye tabdeeli qubool nahi ki.') + ' [' + (code || httpCode) + ']';
} else {
  const why = httpCode === 401 ? 'secret match nahi hua (n8n credential "Header Auth account 2" check karein)'
    : httpCode === 429 ? 'website ne thodi der rukne ko kaha'
    : httpCode === 0 ? 'website tak pohanch nahi saka'
    : 'website ka masla (' + httpCode + ')';
  row.sync_error = 'WF1: RETRY @' + stamp + ' ' + why + ', agle minute dobara.';
}
row.sync_error = String(row.sync_error).slice(0, 500);
return { json: row };
